/* Local contract workspace. Source records stay on the device; browser persistence is notes only. */
(() => {
  'use strict';
  const C=window.FindingsCore, runtime=window.AfterwordRuntime||{extraction:false,preview:true}, esc=escapeHTML;
  const enabled=runtime.extraction===true, KEY='afterword-finding-notes-v1';
  let previewing=false, rows=[], health=null, loading=enabled, error='', loaded=false, refreshedAt=null;
  let selected=null, sourcePage=0, query='', statusFilter='all', categoryFilter='all', memorySaved=false;
  let requestEpoch=0, retrying=new Set(), intake=null, noteAvailable=true;
  let authEpoch=0;
  const notes=new Map();
  function restoreNotes(){try {const data=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(data))for(const pair of data.slice(0,10000)){if(!Array.isArray(pair)||typeof pair[0]!=='string'||!pair[1]||typeof pair[1]!=='object')continue;notes.set(pair[0],{note:typeof pair[1].note==='string'?pair[1].note.slice(0,2000):'',read:pair[1].read===true,saved:pair[1].saved===true,completed:pair[1].completed===true});}}catch{noteAvailable=false;}}
  const canAccess=()=>runtime.workspace?window.AfterwordProfile?.canAccessData()===true:true;
  if(canAccess())restoreNotes();
  window.addEventListener?.('afterword-locked',()=>{authEpoch++;requestEpoch++;rows=[];health=null;notes.clear();loaded=false;loading=false;error='';refreshedAt=null;selected=null;sourcePage=0;query='';retrying.clear();if(intake)intake.stop=true;intake=null;});
  const active=()=>enabled&&!previewing;
  const parts=()=>C.partitionFindings(rows);
  const note=id=>notes.get(id)||{note:'',read:false,saved:false,completed:false};
  const putNote=(id,patch)=>{notes.set(id,{...note(id),...patch});try{localStorage.setItem(KEY,JSON.stringify([...notes]));noteAvailable=true;}catch{noteAvailable=false;}};
  const find=id=>rows.find(row=>row&&row.id===id);
  const title=C.recordTitle;
  const number=value=>value===null?'Not supplied':new Intl.NumberFormat(undefined,{maximumFractionDigits:2}).format(value);
  const href=(route,id)=>'#'+route+(id===undefined?'':'?finding='+encodeURIComponent(id));
  const smallButton=(text,action,extra='')=>`<button class="button" data-action="${action}" ${extra}>${text}</button>`;
  const badge=row=>{const presentation=C.statusPresentation(row);return `<span class="finding-badge finding-${presentation.status||'invalid'}">${esc(presentation.label)}</span>`;};
  const empty=(title,text,extra='')=>`<div class="empty-state"><h2>${esc(title)}</h2><p>${esc(text)}</p>${extra?'<div class="finding-empty-actions">'+extra+'</div>':''}</div>`;
  const field=value=>typeof value==='string'?value:typeof value==='number'?String(value):'Not supplied';
  function headingLive(title,text,actions=true){return heading('YOUR RECORDS',esc(title),esc(text),actions?`<div class="button-row">${smallButton('Refresh','findings-refresh',loading?'disabled':'')}${smallButton('Add records','findings-import','data-primary')}</div>`:'');}
  function statusStrip(){
    if(loading&&!loaded)return '<div class="findings-notice" role="status">Connecting to the local archive…</div>';
    if(error)return `<div class="findings-notice findings-error" role="alert"><div><strong>${loaded?'The archive could not be refreshed.':'The local archive is unavailable.'}</strong><p>${esc(error)} ${loaded?'Your last loaded records remain below.':'No sample records have been substituted.'}</p></div>${smallButton('Try again','findings-refresh',loading?'disabled':'')}</div>`;
    return '';
  }
  function ignoredNotice(){const p=parts();return p.ignored.length?`<p class="fine findings-ignored">${p.ignored.length} irrelevant item${p.ignored.length===1?'':'s'} ignored.</p>`:'';}
  function deadline(row){
    const f=row?.finding||{},provisional=C.fieldNeedsReview(row,'due');
    if(C.validDate(f.deadline_date)){
      const now=new Date(),today=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()),difference=Math.round((Date.parse(f.deadline_date+'T00:00:00Z')-today)/86400000);
      const timing=provisional?'Model-returned date · verify against source':difference<0?Math.abs(difference)+' days past the stated date':difference===0?'Today':difference+' days remaining';
      return `<span class="finding-deadline">${icon('calendar')}<time datetime="${esc(f.deadline_date)}">${esc(formatDate(f.deadline_date))}</time><small>${timing}</small></span>`;
    }
    if(Number.isSafeInteger(f.due))return `<span class="finding-deadline">${icon('calendar')}<span>${provisional?'Model returned '+f.due+' days':f.due+' days stated in the record'}<small>${provisional?'Verify against the source':C.validDate(row.reference_date)?'Calendar date not returned':'No reference date supplied'}</small></span></span>`;
    return '<span class="fine">No stated deadline</span>';
  }
  function amounts(row){const a=C.amountComparison(row),provisional=C.fieldNeedsReview(row,'amt');return `<div class="finding-amounts"><div><span>${provisional?'Printed amount · unverified':'Printed amount'}</span><strong>${esc(number(a.printed))}</strong>${a.recurrence&&a.recurrence!=='none'?`<small>${esc(a.recurrence)}</small>`:''}${provisional?'<small>Verify against the source</small>':''}</div><span aria-hidden="true">${icon('arrow')}</span><div><span>${provisional?'What’s at stake · provisional':'What’s at stake'}</span><strong>${esc(number(a.atStake))}</strong><small>${provisional?'Based on an unverified amount':'Calculated by the local rules'}</small></div></div>`;}
  function reportDeadline(row){const f=row.finding||{},provisional=C.fieldNeedsReview(row,'due');if(C.validDate(f.deadline_date))return f.deadline_date+(provisional?' · Model-returned date; verify against source':'');if(Number.isSafeInteger(f.due))return (provisional?'Model returned '+f.due+' days · Verify against the source':f.due+' days stated in the record')+' · '+(C.validDate(row.reference_date)?'Calendar date not returned':'No reference date supplied');return 'No stated deadline';}
  function reportAmounts(row){const a=C.amountComparison(row),provisional=C.fieldNeedsReview(row,'amt');return 'Printed amount'+(provisional?' (unverified)':'')+': '+number(a.printed)+'; calculated amount at stake'+(provisional?' (provisional)':'')+': '+number(a.atStake)+(a.recurrence&&a.recurrence!=='none'?'; recurrence: '+a.recurrence:'')+'. Currency from source.'+(provisional?' Verify against the source.':'');}
  function reasonMarkup(row){const {reasons,details}=C.reviewPresentation(row);return (reasons.length?`<ul class="finding-reasons">${reasons.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:'')+(details?`<details class="finding-technical"><summary>Technical details</summary><p class="fine">${esc(details)}</p></details>`:'');}
  function actionCard(row){return `<article class="finding-card ${note(row.id).completed?'is-complete':''}"><div class="finding-card-top"><span class="eyebrow">${esc(C.categoryLabel(row.finding?.cat))}</span>${badge(row)}</div><h2><a href="${href('evidence',row.id)}">${esc(C.actionLabel(row.finding?.act))}</a></h2><p class="finding-institution">${esc(title(row))}</p>${amounts(row)}<div class="finding-card-foot">${deadline(row)}<a class="text-link" href="${href('evidence',row.id)}">Review record ${icon('arrow')}</a></div>${note(row.id).completed?'<p class="fine">You marked this action complete.</p>':''}</article>`;}
  function failedSection(){const failed=parts().failed,invalid=parts().invalid.filter(item=>item.result?.status!=='failed');if(!failed.length&&!invalid.length)return '';return `<section class="findings-failures"><div class="section-title"><h2>Records needing attention</h2><span>${failed.length+invalid.length}</span></div>${failed.map(row=>`<div class="finding-failure-row"><div><strong>${esc(title(row))}</strong>${reasonMarkup(row)}</div><a class="button" href="${href('evidence',row.id)}">Review & retry</a></div>`).join('')}${invalid.map(item=>`<div class="finding-failure-row"><div><strong>${esc(title(item.result))}</strong><p>${item.issues.map(esc).join(' ')}</p></div></div>`).join('')}</section>`;}
  function overview(){const p=parts(),open=p.actions.filter(row=>!note(row.id).completed),next=open[0];return headingLive('A clear next step.','Read what the records say, review the uncertain details, and keep the personal things close.')+statusStrip()+`<div class="workspace-metrics"><a href="#documents"><span>Records</span><strong>${rows.length}</strong><small>In the local archive ${icon('arrow')}</small></a><a href="#plan"><span>Open actions</span><strong>${open.length}</strong><small>From your records ${icon('arrow')}</small></a><a href="#evidence"><span>Needs review</span><strong>${p.actions.filter(row=>row.status==='needs_review').length}</strong><small>Check the cited evidence ${icon('arrow')}</small></a><a href="#memories"><span>Memories</span><strong>${p.memories.length}</strong><small>Personal records ${icon('arrow')}</small></a></div><div class="findings-overview"><section><div class="section-title"><h2>Next in your plan</h2><a class="text-link" href="#plan">All actions ${icon('arrow')}</a></div>${next?actionCard(next):empty(loaded?'Nothing waiting in your plan.':'Your records will appear here.',loaded?'Add records to find actions and memories.':'Connect to the local archive to continue.')}</section><aside class="findings-side-note"><h2>Keep the source close.</h2><p>Each finding opens beside the exact text used by the model. A suggested action and an automated check are starting points for your review.</p><a class="text-link" href="#documents">Browse your records ${icon('arrow')}</a>${refreshedAt?`<p class="fine">Last loaded ${esc(formatTime(refreshedAt))}</p>`:''}</aside></div>${failedSection()}${ignoredNotice()}`;}
  function filteredActions(){return parts().actions.filter(row=>(statusFilter==='all'||statusFilter==='completed'?statusFilter==='all'||note(row.id).completed:row.status===statusFilter)&&(categoryFilter==='all'||row.finding?.cat===categoryFilter)&&(title(row)+' '+C.actionLabel(row.finding?.act)+' '+C.categoryLabel(row.finding?.cat)).toLowerCase().includes(query.toLowerCase()));}
  function actionResults(){const list=filteredActions();return list.length?list.map(actionCard).join(''):empty('No actions in this view.','Change a filter or add another record.');}
  function plan(){const categories=[...new Set(parts().actions.map(row=>row.finding?.cat).filter(value=>typeof value==='string'))];return headingLive('Your action plan.','Stated time limits come first, followed by the largest calculated amount at stake.')+statusStrip()+`<div class="button-row">${smallButton('Export plan','findings-export-plan')}</div><div class="findings-toolbar"><label class="search-field">${icon('search')}<input id="findings-query" aria-label="Search actions" placeholder="Search actions or institutions" value="${esc(query)}"></label><label class="compact-field"><span>Status</span><select id="findings-status"><option value="all">All actions</option>${[['accepted','Accepted'],['needs_review','Needs review'],['completed','Marked complete']].map(([value,label])=>`<option value="${value}" ${statusFilter===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="compact-field"><span>Category</span><select id="findings-category"><option value="all">All categories</option>${categories.map(value=>`<option value="${esc(value)}" ${categoryFilter===value?'selected':''}>${esc(C.categoryLabel(value))}</option>`).join('')}</select></label></div><p class="fine findings-amount-note">Amounts are shown as returned by the local model rules. The record determines the currency; an estimate is not confirmation of what is owed or recoverable.</p><div class="findings-grid" id="findings-action-results">${actionResults()}</div>${failedSection()}${ignoredNotice()}`;}
  function documents(){const visible=rows.filter(row=>row&&typeof row==='object'&&(row.route!=='drop'||row.status==='failed'));return headingLive('Your records, together.','Email, messages and letters are kept as individual records with their original extraction text.')+statusStrip()+`<div class="findings-document-list">${visible.map(row=>`<article><span class="file-badge">${icon(row.source==='email'?'mail':row.source==='sms'?'quote':'files')}</span><div><h2><a href="${href('evidence',row.id)}">${esc(title(row))}</a></h2><p>${esc(field(row.source))} · ${esc(row.id)}</p></div>${badge(row)}<a class="icon-button" aria-label="Read ${esc(title(row))}" href="${href('evidence',row.id)}">${icon('chevron')}</a></article>`).join('')||empty('Start with the records you have.','Add an email export, a message archive, or a letter. Each item is processed on the local device.',smallButton('Add records','findings-import'))}</div>${ignoredNotice()}`;}
  function selectedRow(){const id=new URLSearchParams((location.hash.split('?')[1]||'')).get('finding');if(id!==null)return find(id)||null;return find(selected)||parts().actions[0]||parts().failed[0]||parts().memories[0]||null;}
  function sourceMarkup(row){const mapped=C.evidenceLines(row.text,row.evidence),count=mapped.lines.length,pages=Math.max(1,Math.ceil(count/200));sourcePage=Math.min(Math.max(sourcePage,0),pages-1);const start=sourcePage*200;return `<section class="finding-source"><div class="finding-source-header"><h2>Original source</h2><span>${esc(row.source)} · ${count} line${count===1?'':'s'}</span></div>${!mapped.available?'<div class="findings-notice" role="alert">The exact source text was not returned. Refresh before checking the evidence.</div>':`<ol class="finding-source-lines" start="${start+1}">${mapped.lines.slice(start,start+200).map(line=>`<li class="${line.cited?'is-cited':''}" value="${line.number}"><span class="source-line-number" aria-hidden="true">${line.number}</span><code><span class="sr-only">Line ${line.number}: </span>${esc(line.text)}</code>${line.cited?'<span class="sr-only">Cited evidence</span>':''}</li>`).join('')}</ol>`}${pages>1?`<div class="finding-source-pagination">${smallButton('Previous lines','findings-source-prev',sourcePage===0?'disabled':'')}<span>Lines ${start+1}–${Math.min(start+200,count)} of ${count}</span>${smallButton('Next lines','findings-source-next',sourcePage>=pages-1?'disabled':'')}</div>`:''}<p class="fine">Highlighted lines were cited by the model. The source text is unchanged.</p>${mapped.invalidEvidence.length?`<div class="findings-notice findings-error">${mapped.invalidEvidence.length} evidence reference${mapped.invalidEvidence.length===1?' is':'s are'} invalid. ${mapped.invalidEvidence.map(item=>esc(item.reason)).join(' ')}</div>`:''}${mapped.mismatches.length?'<div class="findings-notice findings-error">A returned quotation differs from the stored source. Compare the original text before relying on this finding.</div>':''}</section>`;}
  function evidence(){const row=selectedRow();if(!row)return headingLive('Review the evidence.','Findings will open beside their source record.')+statusStrip()+empty('No record selected.','Add records or choose one from Documents.');if(selected!==row.id){selected=row.id;sourcePage=0;}const f=row.finding||{},n=note(row.id),translatedSummary=[C.actionLabel(f.act),C.categoryLabel(f.cat),...C.reviewPresentation(row).reasons].join('\n');return headingLive(title(row),'Compare the finding with the exact text used for extraction.',false)+statusStrip()+`<div class="findings-evidence-layout"><section class="finding-detail"><div class="finding-card-top">${badge(row)}${window.compactLanguageToggle?.()||''}</div><h2>${esc(row.route==='memory'?'A personal record':C.actionLabel(f.act))}</h2>${reasonMarkup(row)}${row.route==='extract'?amounts(row):''}<dl class="finding-facts"><div><dt>Category</dt><dd>${esc(C.categoryLabel(f.cat))}</dd></div><div><dt>Reference in result</dt><dd>${esc(field(f.ref))}</dd></div><div><dt>Stated timing</dt><dd>${deadline(row)}</dd></div><div><dt>Source ID</dt><dd>${esc(row.id)}</dd></div></dl>${window.translatedBlock?.(translatedSummary,'summary','translated-live-finding-'+Array.from(row.id).map(character=>character.codePointAt(0).toString(16)).join('_'))||''}<div class="finding-citation-links">${[...new Set((Array.isArray(row.evidence)?row.evidence:[]).map(item=>item?.line).filter(value=>Number.isInteger(value)&&value>0))].map(line=>`<button class="text-link" data-action="findings-citation" data-line="${line}">Line ${line}</button>`).join('')}</div><div class="button-row">${smallButton(n.read?'Read · Undo':'Mark as read','findings-read',`data-id="${esc(row.id)}"`)}${row.route==='extract'?smallButton(n.completed?'Reopen action':'Mark complete','findings-complete',`data-id="${esc(row.id)}"`):''}${smallButton(retrying.has(row.id)?'Processing…':'Retry extraction','findings-retry',`data-id="${esc(row.id)}" ${retrying.has(row.id)||typeof row.text!=='string'?'disabled':''}`)}</div><p class="fine">Your read and completion marks do not change the model’s checks.</p><label class="field finding-note"><span>Your review note</span><textarea id="findings-note" data-id="${esc(row.id)}" maxlength="2000" rows="4" placeholder="A question to check or a detail to keep…">${esc(n.note)}</textarea></label><p class="fine" id="findings-note-status">${noteAvailable?'Notes save in this browser.':'Browser storage is unavailable; notes last for this session.'}</p>${smallButton('Download source','findings-download',`data-id="${esc(row.id)}" ${typeof row.text!=='string'?'disabled':''}`)}</section>${sourceMarkup(row)}</div>`;}
  function memories(){const all=parts().memories,list=all.filter(row=>!memorySaved||note(row.id).saved);return headingLive('The personal things.','Letters, messages and notes from your archive. Read them whenever you are ready.')+statusStrip()+`<div class="filter-bar"><button class="filter ${!memorySaved?'selected':''}" data-action="findings-memory-all" aria-pressed="${!memorySaved}">All memories <span>${all.length}</span></button><button class="filter ${memorySaved?'selected':''}" data-action="findings-memory-saved" aria-pressed="${memorySaved}">Saved for later <span>${all.filter(row=>note(row.id).saved).length}</span></button></div><div class="findings-memory-grid">${list.map(row=>`<article class="finding-memory"><div class="finding-card-top"><span>${icon(row.source==='email'?'mail':'book')} ${esc(row.source)}</span><button class="icon-button ${note(row.id).saved?'saved':''}" data-action="findings-favorite" data-id="${esc(row.id)}" aria-label="${note(row.id).saved?'Unsave':'Save'} ${esc(title(row))}" aria-pressed="${note(row.id).saved}">${icon('heart')}</button></div><h2>${esc(title(row))}</h2><p>${esc(typeof row.text==='string'?row.text.slice(0,280)+(row.text.length>280?'…':''):'Source text not available.')}</p><a class="text-link" href="${href('evidence',row.id)}">Read the record ${icon('arrow')}</a></article>`).join('')||empty(memorySaved?'No saved memories yet.':'A place for the personal things.',memorySaved?'Use the heart beside a memory to keep it here.':'Personal records will appear here after processing.')}</div>`;}
  function metric(value,unit=''){return value===null||value===undefined?'Not available':number(value)+(unit?' '+unit:'');}
  function modelPanel(){const m=C.aggregateTelemetry(rows);return `<section class="findings-panel"><div class="section-title"><h2>Local model</h2><span>${esc(typeof health?.model==='string'?health.model:m.models.join(', ')||'Not available')}</span></div><dl class="findings-metric-list"><div><dt>Contract</dt><dd>${esc(health?.contract||C.CONTRACT)}</dd></div><div><dt>Average output tokens / document</dt><dd>${metric(m.outputTokens.mean)}<small>${m.outputTokens.samples} measured records</small></dd></div><div><dt>Average latency / document</dt><dd>${metric(m.latency.meanMs,'ms')}<small>${m.latency.samples} measured records</small></dd></div></dl><p class="fine">These measurements come from the stored model responses. They are not a live hardware benchmark.</p></section>`;}
  function ledger(){const m=C.aggregateTelemetry(rows),telemetry=health?.telemetry||{},entities=telemetry.scope==='current_offline_application'&&Number.isSafeInteger(telemetry.entities_sent_to_cloud)&&telemetry.entities_sent_to_cloud>=0?telemetry.entities_sent_to_cloud:null,cost=typeof telemetry.cloud_equivalent_cost==='number'&&Number.isFinite(telemetry.cloud_equivalent_cost)&&telemetry.cloud_equivalent_cost>=0?telemetry.cloud_equivalent_cost:null;return headingLive('Processing on this device.','An account of where each record was processed and the measurements returned by the model.')+statusStrip()+`<div class="button-row">${smallButton('Export activity','findings-export-activity')}</div><div class="findings-ledger-grid"><section class="findings-panel"><h2>Escalation Ledger</h2><dl class="findings-metric-list">${m.tiers.map(item=>`<div><dt>${esc(item.tier)}</dt><dd>${item.count} items</dd></div>`).join('')||'<div><dt>Processing tiers</dt><dd>Not available</dd></div>'}${m.unknownTierCount?`<div><dt>Tier not reported</dt><dd>${m.unknownTierCount} items</dd></div>`:''}<div><dt>Entities sent to cloud</dt><dd>${metric(entities)}</dd></div><div><dt>Cloud-equivalent cost</dt><dd>${metric(cost)}</dd></div></dl><p class="fine">This count covers the application’s processing boundary. Whole-device traffic, including remote access to the interface, is not measured.${entities!==null&&typeof telemetry.basis==='string'?' '+esc(telemetry.basis):''}</p><p class="fine">Unreported measurements remain unavailable. A cloud cost estimate will appear when the model layer supplies its comparison.</p></section>${modelPanel()}</div>${ignoredNotice()}`;}
  function settings(){return headingLive('Your local workspace.','Reading preferences, connection details, and your notes.',false)+statusStrip()+`<div class="findings-ledger-grid">${modelPanel()}<section class="findings-panel"><h2>Workspace settings</h2><div class="setting-action"><div><h3>Reading preferences</h3><p>Text size, language and background motion.</p></div>${smallButton('Change','preferences')}</div><dl class="findings-metric-list"><div><dt>Record storage</dt><dd>Local device database</dd></div><div><dt>Notes and read marks</dt><dd>${noteAvailable?'This browser':'Session only'}</dd></div><div><dt>Font files</dt><dd>System fonts · no external request</dd></div><div><dt>Last archive refresh</dt><dd>${esc(refreshedAt?formatTime(refreshedAt):'Not loaded')}</dd></div></dl><div class="button-row">${smallButton('Export notes','findings-export-notes')}${smallButton('Open sample preview','findings-preview')}</div><p class="fine">The sample preview is separate from your device records. Opening it does not replace or delete this archive.</p></section></div>`;}
  function privacy(){return headingLive('Your records stay here.','This workspace uses the local device for extraction and record storage.',false)+statusStrip()+`<section class="findings-panel"><h2>What is stored where</h2><dl class="findings-metric-list"><div><dt>Original extraction text and findings</dt><dd>Local database</dd></div><div><dt>Review notes, read marks and favorites</dt><dd>Unencrypted storage in this browser</dd></div><div><dt>Document text in browser storage</dt><dd>Not saved by this workspace</dd></div><div><dt>Extraction endpoint</dt><dd>${esc(location.origin)}</dd></div><div><dt>External model calls</dt><dd>${health?.offline===true?'Disabled by the local service':'Offline service policy not verified'}</dd></div></dl><p>Adding a record sends it to the service at this address. Downloads are created on your computer. Translation, when enabled, applies to summaries and instructions; the original record is kept unchanged.</p><a class="text-link" href="#ledger">View processing measurements ${icon('arrow')}</a></section>`;}
  function letters(){return headingLive('Start with the record.','Confirm the finding and its source before preparing a message.',false)+`<section class="findings-panel"><h2>Letters in this offline workspace</h2><p>External email connections are disabled in this deployment. Review an action and keep your questions in its review note. You can download the source and export your notes for use outside Afterword.</p><a class="button primary" href="#plan">Open your action plan ${icon('arrow')}</a></section>`;}
  function searchPage(){return headingLive('Find a record.','Search the institutions, categories and source text in your local archive.',false)+`<label class="search-field">${icon('search')}<input id="findings-search-records" aria-label="Search local records" placeholder="Search records" value="${esc(query)}"></label><div id="findings-search-results">${searchResults()}</div>`;}
  function searchResults(){const q=query.toLowerCase().trim(),list=rows.filter(row=>row&&typeof row==='object'&&row.route!=='drop'&&(title(row)+' '+(row.text||'')+' '+C.categoryLabel(row.finding?.cat)).toLowerCase().includes(q));return `<p class="fine findings-search-count">${list.length} matching records</p>`+list.slice(0,50).map(row=>`<a class="finding-search-result" href="${href('evidence',row.id)}"><strong>${esc(title(row))}</strong><span>${esc(C.categoryLabel(row.finding?.cat))}</span>${icon('arrow')}</a>`).join('');}
  async function api(path,options={}){
    if(!canAccess())throw new Error('Sign in to your local workspace to continue.');
    const epoch=authEpoch;
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),options.timeout||15000);
    try{const response=await fetch(new URL(path,location.origin).href,{method:options.body?'POST':'GET',headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json','X-Afterword-Client':'web'}:{})},...(options.body?{body:JSON.stringify(options.body)}:{}),signal:controller.signal,credentials:'same-origin',redirect:'error'});let value;try{value=await response.json();}catch{throw new Error('The local service returned an unreadable response.');}if(epoch!==authEpoch)throw new Error('This request belongs to an earlier session.');if(response.status===401)window.AfterwordProfile?.lock();if(!response.ok)throw new Error(typeof value?.detail==='string'?value.detail:value?.detail?.message||value?.error||'The local service could not complete the request.');return value;}catch(cause){if(cause.name==='AbortError')throw new Error('The local service did not respond in time. Processing may still be running; refresh before retrying.');throw cause;}finally{clearTimeout(timer);}
  }
  async function refresh(){
    if(!enabled||!canAccess())return;
    if(!loaded)restoreNotes();
    const epoch=++requestEpoch;loading=true;if(active())render();
    try{
      const [newHealth,collection]=await Promise.all([api('/health'),api('/findings')]);
      if(epoch!==requestEpoch)return;
      if(newHealth.contract!==C.CONTRACT||newHealth.capabilities?.extract!==true)throw new Error('The connected service does not support the required findings contract.');
      if(collection.contract!==C.CONTRACT||!Array.isArray(collection.findings))throw new Error('The archive returned an unsupported findings collection.');
      const ids=collection.findings.filter(row=>row&&typeof row.id==='string').map(row=>row.id);
      if(new Set(ids).size!==ids.length)throw new Error('The archive returned duplicate document identifiers. Refresh after the service is corrected.');
      rows=collection.findings;health=newHealth;loaded=true;refreshedAt=new Date().toISOString();error='';
    }catch(cause){if(epoch===requestEpoch)error=cause.message;}finally{if(epoch===requestEpoch){loading=false;if(active())render();}}
  }
  function download(name,text,type='text/plain'){
    const blob=new Blob([text],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  async function retry(id){const row=find(id);if(!row||typeof row.text!=='string'||retrying.has(id))return;retrying.add(id);render();try{await api('/extract?retry=true',{body:{id:row.id,source:row.source,text:row.text,...(C.validDate(row.reference_date)?{reference_date:row.reference_date}:{})},timeout:180000});await refresh();toast('Record processed. Review the updated result.');}catch(cause){toast(cause.message);}finally{retrying.delete(id);if(active())render();}}
  const allowed=/\.(eml|mbox|csv|xml|txt|md|pdf|png|jpe?g|webp|tiff?)$/i;
  function intakeBody(){const current=intake||{entries:[],reference_date:'',running:false,stop:false},total=current.entries.reduce((sum,item)=>sum+(item.preview?.document_count||0),0);return `<p>Add records to the local service at <strong>${esc(location.origin)}</strong>. Email and message exports are separated into individual records. PDF pages and images are read on this device.</p><label class="field"><span>Date of death / reference date (optional)</span><input type="date" id="findings-reference-date" value="${esc(current.reference_date)}" ${current.running?'disabled':''}><small>Used only to turn stated days into calendar dates. Leave it blank when unknown.</small></label><label class="field"><span>Choose records</span><input id="findings-files" type="file" multiple accept=".eml,.mbox,.csv,.xml,.txt,.md,.pdf,.png,.jpg,.jpeg,.webp,.tif,.tiff" ${current.running?'disabled':''}><small>Up to 10 files · 10 MB each · up to 100 messages or pages per file.</small></label><div id="findings-intake-progress" role="status" aria-live="polite">${intakeProgress()}</div>${total?`<p class="fine">${total} individual records found. Review parser warnings before processing.</p>`:''}<div class="button-row"><button class="button primary" data-action="findings-intake-start" ${current.running||!current.entries.some(item=>['ready','failed','partial'].includes(item.status))?'disabled':''}>${current.entries.some(item=>item.status==='partial'||item.status==='failed')?'Process remaining records':'Process records'}</button>${current.running?smallButton(current.stop?'Stopping after this file…':'Stop after current file','findings-intake-stop',current.stop?'disabled':''):''}</div><p class="fine">Processing is sequential. Closing this dialog does not cancel an active file. Completed records are kept if a later file fails.</p>`;}
  function intakeProgress(){return (intake?.entries||[]).map(item=>`<div class="findings-intake-item"><strong>${esc(item.file.name)}</strong><span>${esc(item.message||item.status)}</span>${item.preview?.warnings?.length?`<p>${item.preview.warnings.map(esc).join(' ')}</p>`:''}${item.errors?.length?`<ul>${item.errors.map(value=>`<li>${esc(value)}</li>`).join('')}</ul>`:''}</div>`).join('')||'<p>No files selected.</p>';}
  function openIntake(){if(!intake)intake={entries:[],reference_date:'',running:false,stop:false};modal('Add records',intakeBody(),smallButton('Close','close-modal'));}
  function updateIntake(){if($('#detail-dialog')?.open&&$('#findings-intake-progress'))openIntake();}
  async function encodeFile(file){const data=new Uint8Array(await file.arrayBuffer());let binary='';for(let index=0;index<data.length;index+=32768)binary+=String.fromCharCode(...data.subarray(index,index+32768));return btoa(binary);}
  async function previewFiles(files){
    if(intake?.running)return;
    const epoch=authEpoch;
    if(!intake)intake={entries:[],reference_date:'',running:false,stop:false};
    if(files.length>10){toast('Choose up to 10 files at a time.');return;}
    const entries=files.map(file=>({file,status:'previewing',message:'Reading file…',errors:[],parserErrors:[],processed:[],content:null,preview:null,remaining:null}));intake.entries=entries;intake.running=true;updateIntake();
    for(const item of entries){
      if(epoch!==authEpoch||!intake)return;
      if(intake.stop){item.status='waiting';item.message='Not read. Select files again to continue.';continue;}
      if(!allowed.test(item.file.name)||!item.file.size||item.file.size>10*1024*1024){item.status='invalid';item.message='Choose a supported, non-empty file no larger than 10 MB.';updateIntake();continue;}
      try{item.content=await encodeFile(item.file);if(epoch!==authEpoch||!intake)return;item.preview=await api('/ingest/preview',{body:{filename:item.file.name,content_base64:item.content},timeout:180000});
        if(!Array.isArray(item.preview.documents)||!Array.isArray(item.preview.errors))throw new Error('The local parser returned an unreadable preview.');
        item.parserErrors=item.preview.errors;item.errors=item.parserErrors.map(entry=>entry.message);item.preview.warnings=[...new Set(item.preview.documents.flatMap(doc=>doc.warnings||[]))];item.status=item.preview.documents.length?'ready':item.parserErrors.some(entry=>entry.retryable)?'failed':'invalid';item.message=item.preview.documents.length+' records ready'+(item.errors.length?' · '+item.errors.length+' could not be read':'');
      }catch(cause){item.status='failed';item.message=cause.message;}updateIntake();
    }
    if(epoch!==authEpoch||!intake)return;
    intake.running=false;intake.stop=false;updateIntake();
  }
  async function processIntake(){
    if(!intake||intake.running)return;const reference=$('#findings-reference-date')?.value||intake.reference_date;
    const epoch=authEpoch;
    if(reference&&!C.validDate(reference)){toast('Enter a valid reference date or leave it blank.');return;}
    intake.reference_date=reference;intake.running=true;intake.stop=false;updateIntake();
    try{for(const item of intake.entries){
      if(epoch!==authEpoch||!intake)return;
      if(intake.stop)break;if(!['ready','failed','partial'].includes(item.status))continue;
      if(!item.content){item.status='failed';item.message='Select the original file again.';continue;}
      item.status='processing';item.message='Processing '+(item.remaining?.length||item.preview?.document_count||'the')+' records on the local model…';updateIntake();
      try{const response=await api('/ingest/extract'+(item.remaining?.length?'?retry=true':''),{body:{filename:item.file.name,content_base64:item.content,...(reference?{reference_date:reference}:{}),...(item.remaining?.length?{document_ids:item.remaining}:{})},timeout:1200000});
        if(!Array.isArray(response.results))throw new Error('The extraction response did not contain results. Refresh the archive before retrying.');
        const returnedIDs=new Set(response.results.map(row=>row.id));
        item.remaining=[...new Set([...(item.remaining||[]).filter(id=>!returnedIDs.has(id)),...response.results.filter(row=>row.status==='failed').map(row=>row.id)])];
        const parsedIDs=new Set([...(Array.isArray(response.documents)?response.documents:[]).map(document=>document.id),...returnedIDs]);
        const errorKey=entry=>typeof entry.id==='string'?'id:'+entry.id:'position:'+String(entry.position)+':'+String(entry.message);
        const parserErrors=new Map((item.parserErrors||[]).filter(entry=>!parsedIDs.has(entry.id)).map(entry=>[errorKey(entry),entry]));
        for(const entry of response.errors||[])parserErrors.set(errorKey(entry),entry);
        item.parserErrors=[...parserErrors.values()];item.errors=item.parserErrors.map(entry=>entry.message);
        item.processed=[...new Set([...(item.processed||[]).filter(id=>!returnedIDs.has(id)),...response.results.filter(row=>row.status!=='failed').map(row=>row.id)])];
        item.status=item.remaining.length||item.errors.length?'partial':'complete';item.message=item.processed.length+' records processed'+(item.remaining.length?' · '+item.remaining.length+' need another attempt':'')+(item.errors.length?' · '+item.errors.length+' parser errors':'');
      }catch(cause){item.status='failed';item.message=cause.message;}if(epoch!==authEpoch||!intake)return;await refresh();updateIntake();
    }}finally{if(epoch===authEpoch&&intake){intake.running=false;intake.stop=false;updateIntake();if(active())render();}}
  }
  const oldPrepare=window.prepareRoute;
  window.prepareRoute=()=>{if(!active()){oldPrepare?.();return;}const raw=location.hash.slice(1).split('?')[0]||'overview';state.route=raw==='privacy'?'exposure':raw==='design'?'settings':([...nav.map(item=>item[0]),'ask','profile'].includes(raw)?raw:'overview');state.linkedDocument=null;};
  const views={overview,plan,documents,evidence,memories,ledger,settings,exposure:privacy,letters,ask:searchPage};
  for(const [name,view]of Object.entries(views)){const previous=window.views[name];window.views[name]=()=>active()?view():previous?.()||'';}
  const oldImport=window.openImport;window.openImport=()=>active()?openIntake():oldImport?.();
  Object.assign(window.actions,{
    'findings-refresh':()=>refresh(),'findings-import':()=>openIntake(),'findings-retry':element=>retry(element.dataset.id),
    'findings-source-prev':()=>{sourcePage--;render();},'findings-source-next':()=>{sourcePage++;render();},'findings-citation':element=>{sourcePage=Math.floor((Number(element.dataset.line)-1)/200);render();$('.finding-source')?.scrollIntoView({block:'start'});},
    'findings-read':element=>{putNote(element.dataset.id,{read:!note(element.dataset.id).read});render();},
    'findings-complete':element=>{putNote(element.dataset.id,{completed:!note(element.dataset.id).completed});render();},
    'findings-favorite':element=>{putNote(element.dataset.id,{saved:!note(element.dataset.id).saved});render();},
    'findings-memory-all':()=>{memorySaved=false;render();},'findings-memory-saved':()=>{memorySaved=true;render();},
    'findings-download':element=>{const row=find(element.dataset.id);if(typeof row?.text==='string')download('afterword-source-'+row.id.replace(/[^\w.-]/g,'_')+'.txt',row.text);},
    'findings-export-plan':async()=>{try{await window.AfterwordReports.downloadPlan({mode:'live',scope:'Current action plan filters',items:filteredActions().map(row=>({id:row.id,title:C.actionLabel(row.finding?.act)+' — '+title(row),status:note(row.id).completed?'Marked complete':C.statusPresentation(row).label,category:C.categoryLabel(row.finding?.cat),date:reportDeadline(row),source:row.source+' · '+row.id,amount:reportAmounts(row),note:note(row.id).note||'',details:C.reviewPresentation(row).reasons.join(' ')}))});toast('Action plan PDF downloaded.');}catch(e){toast('PDF export failed: '+e.message);}},
    'findings-export-activity':async()=>{try{await window.AfterwordReports.downloadActivity({mode:'live',scope:'Processing history retained in the local archive',items:rows.map(row=>({id:row.id,text:title(row),at:row.created_at,status:C.statusPresentation(row).label,source:row.source,details:'Processing tier: '+field(row.meta?.tier)+'. This records processing, not a completed family action.'}))});toast('Activity PDF downloaded.');}catch(e){toast('PDF export failed: '+e.message);}},
    'findings-export-notes':()=>download('afterword-review-notes.json',JSON.stringify({exported_at:new Date().toISOString(),notes:[...notes].map(([id,value])=>({id,...value}))},null,2),'application/json'),
    'findings-preview':()=>{previewing=true;closeDialog();go('overview');render();},'findings-live':()=>{previewing=false;closeDialog();go('overview');refresh();},
    'findings-intake-start':()=>processIntake(),'findings-intake-stop':()=>{if(intake){intake.stop=true;updateIntake();}}
  });
  const previousInfo=window.actions['workspace-info'],previousCommand=window.actions.command;
  window.actions['workspace-info']=()=>active()?modal('Your local archive','<p>Your uploaded records are stored and processed by the service on this device. Review the exact source before acting on a finding. The model weights can change without changing the finding contract.</p>',smallButton('Back to workspace','close-modal')):previousInfo?.();
  window.actions.command=()=>active()?go('ask'):previousCommand?.();
  document.addEventListener('input',event=>{
    if(!active())return;
    if(event.target.id==='findings-query'){query=event.target.value;$('#findings-action-results').innerHTML=actionResults();}
    if(event.target.id==='findings-search-records'){query=event.target.value;$('#findings-search-results').innerHTML=searchResults();}
    if(event.target.id==='findings-note'){putNote(event.target.dataset.id,{note:event.target.value});$('#findings-note-status').textContent=noteAvailable?'Saved in this browser.':'Session only. Export your notes before leaving.';}
  });
  document.addEventListener('change',event=>{
    if(!active())return;
    if(event.target.id==='findings-status'){statusFilter=event.target.value;render();}
    if(event.target.id==='findings-category'){categoryFilter=event.target.value;render();}
    if(event.target.id==='findings-reference-date'&&intake)intake.reference_date=event.target.value;
    if(event.target.id==='findings-files')previewFiles([...event.target.files]);
  });
  const previousAfterRender=afterRender;
  afterRender=()=>{
    previousAfterRender();
    if(!active()){
      if(previewing&&!$('#findings-preview-notice'))$('#main')?.insertAdjacentHTML('afterbegin',`<div class="findings-notice" id="findings-preview-notice"><p>You are viewing fictional sample records. Your local archive is unchanged.</p>${smallButton('Return to local archive','findings-live')}</div>`);
      return;
    }
    const set=(selector,text)=>{const element=$(selector);if(element)element.textContent=text;};
    set('.estate-label strong','Local archive');set('.estate-label small','Family workspace');set('.estate-label .avatar','A');$('.estate-label')?.setAttribute('aria-label','About this local archive');
    set('.profile strong','Your workspace');set('.profile small','On this device');set('.profile .avatar','A');
    const node=$('.node-label>span');if(node)node.innerHTML='Local archive<small>'+esc(loading?'Refreshing…':error?'Connection needs attention':'Records on this device')+'</small>';
    set('.demo-label','LOCAL');set('.footnote>span:nth-child(2)','Local records · Review before acting');
    set('.nav-link[href="#plan"] .count',String(parts().actions.filter(row=>!note(row.id).completed).length));
    const search=$('.ask-button');if(search){search.href='#ask';search.setAttribute('aria-label','Search local records');const copy=search.querySelector('span');if(copy)copy.textContent='Search records';}
    if(!noteAvailable&&!$('#findings-storage-warning'))$('#main')?.insertAdjacentHTML('afterbegin','<div class="findings-notice" id="findings-storage-warning">Browser storage is unavailable. Export your review notes before closing this page.</div>');
  };
  window.AfterwordFindings={active,refresh,summary:()=>({active:active(),loaded,loading,error,documents:rows.length,actions:parts().actions.length,memories:parts().memories.length,ignored:parts().ignored.length,failed:parts().failed.length}),getRecord:find};
  if(enabled)refresh();
})();
